/* assets/engine.js —— 由 game.html 的代码**原样外移**而成（只搬位置，函数体/变量名一字未改）
   导出：文件末尾用 window.<name> 挂回全局，供 game.html 内联代码继续直接使用。 */
var __ENGINE_INSTANCES = [];

var __ENGINE = null;

function createEngineInstance(name) {
  var inst = {
    name: name || ('engine#' + (__ENGINE_INSTANCES.length + 1)),
    allCards: __cardListForNewInstance(),
    battleState: null,
    battleLogs: [],
    publicGraveyard: { event_cards: [], music_cards: [] },
    effectEngine: {
      pendingTargetCallback: null, pendingTimingCallback: null, effectLog: [], chainStack: [],
      isProcessing: false, _resolveDepth: 0
    }
  };
  __ENGINE_INSTANCES.push(inst);
  if (!__ENGINE) __ENGINE = inst;
  return inst;
}

function __engineInstance() {
  if (__ENGINE_BUSY) return __ENGINE_BUSY;          // 事件处理期间钉住实例：别的房间切不走
  if (!__ENGINE) createEngineInstance('default');
  return __ENGINE;
}

/* ===== 结算深度：唯一入口（2026-10-06 结构收敛）=====
   原先 _resolveDepth 的 ++/-- 散落在 5 对共 10 处，每处都要人记得配对 ——
   任何一处漏配对就是"永久结算中"（卡死族）。这里把增减收敛成两个函数，
   行为与原来完全等价（+1 / max(0,-1)），但从此**只有这两个函数**能改深度。
   附带只读账本：window.__DEPTH_TRACE = true 时记录 who / 前后值 / 调用栈，
   用于对账"哪处 +1 没有配对的 -1"（默认关闭，零行为影响）。 */
function __eeDepthBook(where, from, to) {
  try {
    /* 【2026-10-07】常开的**环形记录**（最近 12 笔增减，开销可忽略、不改变任何行为）：
       强解时把它打出来，就能直接看出"哪一笔 +1 没有配上 -1"。
       以前只有 window.__DEPTH_TRACE 才记录，而那个开关在实战里没人会去开
       ⇒ 线上出问题时拿不到现场（这正是"效果锁"排查一直卡住的原因）。 */
    try {
      var ee0 = (typeof effectEngine !== 'undefined') ? effectEngine : null;
      if (ee0) {
        var ring = ee0._depthRing || (ee0._depthRing = []);
        ring.push({ w: String(where), d: to - from, to: to, t: Date.now() });
        if (ring.length > 12) ring.splice(0, ring.length - 12);
      }
    } catch (e2) {}
    if (typeof window === 'undefined' || !window.__DEPTH_TRACE) return;
    (window.__DEPTH_LOG = window.__DEPTH_LOG || []).push({
      w: where, from: from, to: to, d: to - from, t: Date.now(),
      stack: String((new Error()).stack || '').split('\n').slice(2, 6).join(' | ')
    });
  } catch (e) {}
}
function __eeDepthAdd(ee, where) {
  if (!ee) return;
  var from = ee._resolveDepth || 0;
  ee._resolveDepth = from + 1;
  __eeDepthBook(where, from, from + 1);
}
function __eeDepthSub(ee, where) {
  if (!ee) return;
  var from = ee._resolveDepth || 0;
  var to = Math.max(0, (from || 1) - 1);
  ee._resolveDepth = to;
  __eeDepthBook(where, from, to);
}

var __ENGINE_BUSY = null;

function __defEngineState(name, initValue) {
  function seed(inst) {
    if (inst[name] === undefined) {
      inst[name] = (typeof initValue === 'function') ? initValue() : initValue;
    }
    return inst[name];
  }
  try {
    Object.defineProperty(globalThis, name, {
      configurable: true,
      enumerable: true,
      get: function () { var inst = __engineInstance(); return seed(inst); },
      set: function (v) { __engineInstance()[name] = v; }
    });
  } catch (e) {
    // 极端情况（某个环境不让重定义）：退回普通全局赋值，保证不崩、行为与改造前一致
    try { globalThis[name] = (typeof initValue === 'function') ? initValue() : initValue; } catch (e2) {}
  }
  seed(__engineInstance());
}

var __CARD_DEFS = null;

function __deepCopyCards(list) {
  try { return JSON.parse(JSON.stringify(list || [])); } catch (e) { return (list || []).slice(); }
}

function __cardMaster() {
  if (!__CARD_DEFS) {
    var cur = (__ENGINE && __ENGINE.allCards) || [];
    if (cur.length) __CARD_DEFS = __deepCopyCards(cur);
  }
  return __CARD_DEFS;
}

function __cardListForNewInstance() { var m = __cardMaster(); return m ? __deepCopyCards(m) : []; }

