// ========== 卡组配置 ==========
/* ============================================================
   【2026-10-03 清单③·本地先行的"多套卡组存档"】账号后端未接之前的可用版本
   · 存储：localStorage('ruzju_deck_library') = [{ id, name, mode, chars[], items[], carries[], ts }]
     —— **按卡名存**（卡表改了也不会错位），读取时再按名字回卡池取卡
   · API：__deckLibAll() / __deckLibSaveCurrent(name) / __deckLibApply(id) / __deckLibDelete(id) / __deckLibRename(id, name)
   ============================================================ */
var __deckLibKey = 'ruzju_deck_library';
function __deckLibAll() { try { var a = JSON.parse(localStorage.getItem(__deckLibKey) || '[]'); return Array.isArray(a) ? a : []; } catch (e) { return []; } }
function __deckLibWrite(arr) { try { localStorage.setItem(__deckLibKey, JSON.stringify(arr)); return true; } catch (e) { return false; } }
function __deckLibNewId() { try { return 'd' + Date.now().toString(36) + Math.floor(Math.random() * 1e4).toString(36); } catch (e) { return 'd' + Date.now(); } }
/** 按名字回卡池取一张卡（依次找 allCards / cardData 各分区 / 肉鸽数据） */
function __deckCardByName(name) {
  try {
    if (!name) return null;
    var pools = [];
    try { if (typeof allCards !== 'undefined' && allCards && allCards.length) pools.push(allCards); } catch (e) {}
    try { if (window.cardData) { ['characters','attack_cards','skill_cards','item_permanent','item_single','gift_cards','music_cards','event_cards','omikuji'].forEach(function (k) { if (Array.isArray(window.cardData[k])) pools.push(window.cardData[k]); }); } } catch (e) {}
    try { if (window.rogueCardData) { Object.keys(window.rogueCardData).forEach(function (k) { if (Array.isArray(window.rogueCardData[k])) pools.push(window.rogueCardData[k]); }); } } catch (e) {}
    for (var i = 0; i < pools.length; i++) {
      for (var j = 0; j < pools[i].length; j++) { if (pools[i][j] && pools[i][j].name === name) return JSON.parse(JSON.stringify(pools[i][j])); }
    }
  } catch (e) {}
  return null;
}
function __deckLibCurrentConfig() {
  try {
    if (typeof deckConfig === 'undefined' || !deckConfig) return null;
    return deckConfig.p1 || null;
  } catch (e) { return null; }
}
function __deckLibSaveCurrent(name) {
  try {
    var cfg = __deckLibCurrentConfig(); if (!cfg) return null;
    var rec = {
      id: __deckLibNewId(), name: String(name || ('卡组 ' + new Date().toLocaleString())), mode: 'local', ts: Date.now(),
      chars: (cfg.chars || []).map(function (c) { return c && c.name || null; }),
      items: (cfg.items || []).map(function (c) { return c && c.name || null; }),
      carries: (cfg.carries || []).map(function (c) { return c && c.name || null; })
    };
    var arr = __deckLibAll(); arr.unshift(rec); __deckLibWrite(arr);
    try { addBattleLog('system', '【卡组存档】已保存「' + rec.name + '」（本机共 ' + arr.length + ' 套）'); } catch (e) {}
    try { showToast('已保存卡组「' + rec.name + '」', 'info'); } catch (e) {}
    __deckLibRenderBar();
    return rec.id;
  } catch (e) { console.error('保存卡组出错', e); return null; }
}
function __deckLibApply(id) {
  try {
    var arr = __deckLibAll(), rec = null;
    for (var i = 0; i < arr.length; i++) if (arr[i].id === id) { rec = arr[i]; break; }
    if (!rec) { try { showToast('找不到这套卡组', 'warn'); } catch (e) {} return false; }
    var cfg = __deckLibCurrentConfig(); if (!cfg) return false;
    var fill = function (names, n) {
      var out = [];
      for (var k = 0; k < n; k++) { out.push(names && names[k] ? __deckCardByName(names[k]) : null); }
      return out;
    };
    cfg.chars = fill(rec.chars, 3);
    cfg.items = fill(rec.items, 8);
    cfg.carries = fill(rec.carries, 4);
    try { if (typeof renderDeckBuilder === 'function') renderDeckBuilder(); } catch (e) {}
    try { if (typeof __saveDeckSets === 'function') { try { __saveDeckSets(); } catch (e2) {} } } catch (e) {}
    try { addBattleLog('system', '【卡组存档】已套用「' + rec.name + '」'); } catch (e) {}
    try { showToast('已套用卡组「' + rec.name + '」', 'info'); } catch (e) {}
    return true;
  } catch (e) { console.error('套用卡组出错', e); return false; }
}
function __deckLibDelete(id) {
  try {
    var arr = __deckLibAll(), out = arr.filter(function (r) { return r.id !== id; });
    __deckLibWrite(out);
    try { showToast('已删除该卡组存档', 'info'); } catch (e) {}
    __deckLibRenderBar();
    return true;
  } catch (e) { return false; }
}
function __deckLibRename(id, name) {
  try {
    var arr = __deckLibAll();
    for (var i = 0; i < arr.length; i++) if (arr[i].id === id) { arr[i].name = String(name || arr[i].name); arr[i].ts = Date.now(); }
    __deckLibWrite(arr); __deckLibRenderBar(); return true;
  } catch (e) { return false; }
}
/* —— 配置页顶部的一排按钮 —— */
function __deckLibSavePrompt() {
  try {
    var cur = '';
    try { cur = (__deckLibAll()[0] && __deckLibAll()[0].name) || ''; } catch (e) {}
    var nm = (typeof prompt === 'function') ? prompt('给这套卡组起个名字：', cur || ('卡组 ' + new Date().toLocaleDateString())) : ('卡组 ' + Date.now());
    if (nm === null || nm === undefined || !String(nm).trim()) return;
    __deckLibSaveCurrent(String(nm).trim());
  } catch (e) {}
}
function __deckLibRenderBar() {
  try {
    var host = document.getElementById('deckLibBar'); if (!host) return;
    var arr = __deckLibAll();
    var opts = arr.map(function (r) { return '<option value="' + r.id + '">' + String(r.name).replace(/[<>&]/g, '') + '</option>'; }).join('');
    host.innerHTML =
      '<span style="font-size:12px;color:#cde;margin-right:6px;">📚 我的卡组（' + arr.length + '）</span>' +
      '<select id="deckLibSel" style="max-width:190px;padding:3px 6px;border-radius:6px;background:#1b2237;color:#e8eefc;border:1px solid rgba(255,255,255,.2);">' + (opts || '<option value="">（还没有存档）</option>') + '</select>' +
      '<button type="button" onclick="__deckLibSavePrompt()" style="margin-left:6px;">💾 存为…</button>' +
      '<button type="button" onclick="var s=document.getElementById(\'deckLibSel\'); if(s&&s.value)__deckLibApply(s.value);" style="margin-left:4px;">📂 读取</button>' +
      '<button type="button" onclick="var s=document.getElementById(\'deckLibSel\'); if(s&&s.value){if(confirm(\'删除这套卡组存档？\'))__deckLibDelete(s.value);}" style="margin-left:4px;">🗑 删除</button>';
  } catch (e) {}
}


const DECK_ATTR_COLOR = { '无序': '#94a3b8', '热忱': '#e94560', '理智': '#4a9eff', '混沌': '#a855f7' };
const ATTR_COLOR = DECK_ATTR_COLOR; // 全局唯一四属性配色（红热忱/蓝理智/灰无序/紫混沌，对齐查询站）

function deckAutoFill(player) {
  var cfg = deckConfig[player];
  if ((cfg.chars || []).filter(Boolean).length < 3) { showToast('请先选满3名角色，再按属性配额补全道具', 'warn'); return; }
  cfg.items = autoFillItems(cfg.chars, cfg.items);
  renderDeckSide(player);
}


function createDeckSlot(card, player, type, index) {
  if (card) {
    var html = '<div class="deck-slot filled" onclick="openCardPicker(\'' + player + '\', \'' + type + '\', ' + index + ')">';
    if (card.image_url) {
      html += '<img loading="lazy" decoding="async" onerror="imgRetry(this)" src="' + card.image_url + '" alt="' + card.name + '">';
    }
    html += '<div class="deck-slot-name">' + card.name + '</div>';
    html += '<div class="deck-slot-remove" onclick="event.stopPropagation();removeCard(\'' + player + '\', \'' + type + '\', ' + index + ')">✕</div>';
    html += '</div>';
    return html;
  } else {
    return '<div class="deck-slot" onclick="openCardPicker(\'' + player + '\', \'' + type + '\', ' + index + ')">+</div>';
  }
}

function removeCard(player, type, index) {
  deckConfig[player][type][index] = null;
  renderDeckSide(player);
}


function openCardPicker(player, type, index) {
  pickerState = { player: player, type: type, index: index };
  
  var picker = document.getElementById('cardPicker');
  var grid = document.getElementById('cardPickerGrid');
  
  // 根据类型筛选可选卡牌
  var availableCards = [];
  if (type === 'chars') {
    availableCards = allCards.filter(function(c) { return c._category === 'characters'; });
  } else if (type === 'items') {
    var usedItemNames = deckConfig[player].items.filter(Boolean).map(function(c){return c.name;});
    var __permN = deckConfig[player].items.filter(function(c){return c && c._category==='item_permanent';}).length;
    var __info = computeAttrRequirement((deckConfig[player].chars||[]).filter(Boolean));
    var __have = {};
    deckConfig[player].items.forEach(function(c){ if(c&&c.attribute) __have[c.attribute]=(__have[c.attribute]||0)+1; });
    pickerState.disabled = {}; // 完整列出全部道具，不可选项只置灰标注、不再直接隐藏（此前已选/永续满会从列表消失，导致列表不全）
    availableCards = allCards.filter(function(c) {
      if (c._category !== 'item_permanent' && c._category !== 'item_single') return false;
      if (usedItemNames.indexOf(c.name) >= 0) { pickerState.disabled[c.name] = '已在卡组中（同名不重复）'; }
      else if (c._category === 'item_permanent' && __permN >= 2) { pickerState.disabled[c.name] = '永续卡最多2张'; }
      return true;
    });
    availableCards.sort(function(a,b){ // 缺额属性最前，灵活位次之，已满足/特殊属性垫底
      function rank(c){ if(__info.req[c.attribute]!=null){var lack=__info.req[c.attribute]-(__have[c.attribute]||0); return lack>0?(-lack):5;} return __info.flexSlots>0?3:9; }
      var d=rank(a)-rank(b); return d!==0?d:((b.score||5)-(a.score||5));
    });
  } else if (type === 'carries') {
    // 携带卡只能选已选角色的攻击卡和技能卡
    var selectedChars = deckConfig[player].chars.filter(function(c) { return c !== null; });
    var charNames = selectedChars.map(function(c) { return c.name; });
    var usedCarryNames = deckConfig[player].carries.filter(Boolean).map(function(c){return c.name;});
    availableCards = allCards.filter(function(c) {
      if (c._category !== 'attack_cards' && c._category !== 'skill_cards') return false;
      if (usedCarryNames.indexOf(c.name) >= 0) return false; // 同名携带不重复
      return cardBelongsToTeam(c, charNames); // 同名不同形态不通用，精确归属
    });
  }
  
  if (availableCards.length === 0) {
    var msg = type === 'carries' ? '请先选择角色卡，携带卡需与已选角色对应' : '暂无可用卡牌';
    grid.innerHTML = '<div style="text-align:center;color:rgba(255,255,255,0.5);padding:40px;">' + msg + '</div>';
  } else {
    var html = '';
    for (var i = 0; i < availableCards.length; i++) {
      var card = availableCards[i];
      var idx = allCards.indexOf(card);
      var __disReason = (type === 'items' && pickerState.disabled) ? (pickerState.disabled[card.name] || '') : '';
      var __onClick = __disReason ? ('showPickerTip("' + __disReason + '")') : ('selectCard(' + idx + ')');
      html += '<div class="card-picker-item' + (__disReason ? ' picker-disabled' : '') + '"' + (__disReason ? ' title="' + __disReason + '"' : '') + ' onclick="' + __onClick + '">';
      if (card.image_url) {
        html += '<img loading="lazy" decoding="async" onerror="imgRetry(this)" src="' + card.image_url + '" alt="' + card.name + '">';
      }
      html += '<div class="card-picker-item-name">' + card.name + '</div>';
      if (type === 'items' && card.attribute) {
        var __ac = (typeof DECK_ATTR_COLOR!=='undefined' && DECK_ATTR_COLOR[card.attribute]) || '#cdd7f0';
        html += '<div style="position:absolute;top:4px;left:4px;background:'+__ac+';color:#101830;font-size:10px;font-weight:700;border-radius:8px;padding:0 6px">'+card.attribute+'</div>';
      }
      html += '</div>';
    }
    grid.innerHTML = html;
  }
  
  picker.classList.add('active');
}

function selectCard(cardIndex) {
  var card = allCards[cardIndex];
  if (!card) return;
  var pl = pickerState.player, ty = pickerState.type, idx = pickerState.index, cfg = deckConfig[pl];
  function others(){ return cfg[ty].filter(function(c,k){ return c && k !== idx; }); }
  if (ty === 'chars') {
    if (others().some(function(c){ return c.name === card.name; })) { showToast('该角色已在队伍中，不能重复选择', 'warn'); return; }
  } else if (ty === 'items') {
    if (others().some(function(c){ return c.name === card.name; })) { showToast('同名道具不能重复加入', 'warn'); return; }
    if (card._category === 'item_permanent' && others().filter(function(c){return c._category==='item_permanent';}).length >= 2) { showToast('永续道具最多只能携带2张', 'warn'); return; }
  } else if (ty === 'carries') {
    if (others().some(function(c){ return c.name === card.name; })) { showToast('同名携带卡不能重复加入', 'warn'); return; }
    var __nm = cfg.chars.filter(Boolean).map(function(c){return c.name;});
    if (!cardBelongsToTeam(card, __nm)) { showToast('携带卡【'+card.name+'】不属于所选3名角色（同名不同形态不通用）', 'warn'); return; }
  }
  cfg[ty][idx] = card;
  closeCardPicker();
  renderDeckSide(pl);
}

// ========== 智能编组 ==========
// 流派归一化（数据中存在别名/近义命名）
var ARCH_ALIASES = {
  '位移队': ['位移队', '移动造伤队'],
  '判定伤害队': ['判定伤害队'],
  '快攻侵略队': ['快攻侵略队', '热忱快攻队', '进攻队'],
  '资源运转队': ['资源运转队', '资源运转流'],
  '破局队': ['破局队', '破局流'],
  '控场队': ['控场队']
};
var ARCH_LIST = Object.keys(ARCH_ALIASES);
function archOf(card, arch) {
  var aliases = ARCH_ALIASES[arch] || [arch];
  var as = card.archetypes || [];
  return as.some(function(a) { return aliases.some(function(x) { return a === x || a.indexOf(x) >= 0 || x.indexOf(a) >= 0; }); });
}
function cScore(c) { return (typeof c.score === 'number' && !isNaN(c.score)) ? c.score : 5; }
function nameHit(a, b) { return a && b && (a.indexOf(b) >= 0 || b.indexOf(a) >= 0); }
// 【唯一权威】卡牌是否属于所选队伍：同名不同形态不通用。
// character_full 精确匹配；缺 full 时按短名包含匹配（如"里绪"→"现实间里绪"、"枫"→"入间枫"、"予"→"入间予"），
// 但队伍角色是"X(水着)"形态时，卡面归属也必须写明"(水着)"才归属（普通形态卡不得借用水着角色编入使用）
function cardBelongsToTeam(card, teamNames) {
  if (!card) return false;
  if (card.character_full) return teamNames.indexOf(card.character_full) >= 0;
  if (card.character) {
    var __ch = card.character;
    return teamNames.some(function (n) {
      if (n === __ch) return true;
      if (n.indexOf('水着') >= 0 && __ch.indexOf('水着') < 0) return false; // 水着形态与普通形态互斥
      return n.indexOf(__ch) >= 0;
    });
  }
  return false;
}
/* 【2026-10-07 新增·**额外同步值使用条件**的唯一入口】
   卡面："这张卡需要支付 7 点同步值才能使用" ⇒ **前置条件**（同步<7 不能用）+ 使用时扣 7（作者的裁决）。
   为什么单独抽一个函数：判定（evaluatePlayable 灰卡）与扣费（使用路径）必须**同一份数据**，
   否则一定会出现"界面能点、扣费却没扣"或反过来的错位。
   将来别的卡加同类条件，往这张表里加一行即可。 */
var EXTRA_SYNC_COST = { '镌刻的艺术': 7 };
function __extraSyncCostOf(card) {
  try {
    if (!card) return 0;
    var n = String(card.name || '');
    for (var k in EXTRA_SYNC_COST) { if (Object.prototype.hasOwnProperty.call(EXTRA_SYNC_COST, k) && n.indexOf(k) >= 0) return EXTRA_SYNC_COST[k]; }
    return 0;
  } catch (e) { return 0; }
}
/* 【2026-10-07 新增·**规则上的属性别名**】
   卡面写"这张卡在规则上还能当作 X 属性使用"时，**卡组构建与效果判定都要认**（作者 2026-10-07 明确：都管）。
   所以要有一个**唯一入口**来问"这张卡在规则上算什么属性" —— 各处都调它，不要各自去读 card.attribute
   （那正是"同一件事多份实现"的老毛病，一定会漏）。
   目前只有镌刻的艺术（混沌 ⇒ 规则上也可作无序）。 */
function __ruleAttrOf(card) {
  try {
    if (!card) return '';
    /* 【2026-10-07】**优先读数据里的声明**（rule_attr）——这是唯一来源：
       查询站（query.html 的编组界面）与对战站都要认同一条规则，写两处必然漂移。
       名字兜底只为兼容"数据还没带上该字段"的旧数据。 */
    if (card.rule_attr) return String(card.rule_attr);
    var n = String(card.name || '');
    if (n.indexOf('镌刻的艺术') >= 0) return '无序';   /* 卡面：「这张卡在规则上还能当作无序属性的卡使用」 */
    return card.attribute || '';
  } catch (e) { return (card && card.attribute) || ''; }
}
// 【道具属性硬需求】默认2无序 + 每名非混沌角色对应属性2；混沌角色不占硬需求(留灵活位)。返回需求表/硬需求总数/灵活位数
function computeAttrRequirement(chars) {
  var req = { '无序': 2 };
  (chars || []).filter(Boolean).forEach(function (c) { if (c.attribute && c.attribute !== '混沌') req[c.attribute] = (req[c.attribute] || 0) + 2; });
  var hardTotal = 0; for (var k in req) hardTotal += req[k];
  var chaosN = (chars || []).filter(Boolean).filter(function (c) { return c.attribute === '混沌'; }).length;
  return { req: req, hardTotal: hardTotal, flexSlots: 8 - hardTotal, chaosN: chaosN };
}
function __allItemCards() { return allCards.filter(function (c) { return c._category === 'item_permanent' || c._category === 'item_single'; }); }
// 在保留已选(非null)的前提下，按硬需求补全到8张；全程不重复、永续≤2。scoreFn 决定同属性内优先级
function autoFillItems(chars, current, scoreFn) {
  var info = computeAttrRequirement(chars), req = info.req;
  var out = (current || []).slice(0, 8).concat(Array(8).fill(null)).slice(0, 8);
  var used = {}, permN = 0, have = {};
  out.forEach(function (c) { if (c) { used[c.name] = 1; if (c.attribute) have[c.attribute] = (have[c.attribute] || 0) + 1; if (c._category === 'item_permanent') permN++; } });
  var pool = __allItemCards();
  function sc(c) { return scoreFn ? scoreFn(c) : (typeof cScore === 'function' ? cScore(c) : (c.score || 5)); }
  function fill(attr, needCount) {
    var cand = pool.filter(function (c) {
      if (used[c.name]) return false;
      if (c._category === 'item_permanent' && permN >= 2) return false;
      if (attr && c.attribute !== attr) return false;
      return true;
    }).sort(function (a, b) { return sc(b) - sc(a); });
    for (var i = 0; i < cand.length && needCount > 0; i++) {
      var c = cand[i];
      if (c._category === 'item_permanent' && permN >= 2) continue; // 循环内复查，防止同一轮选出第3张永续
      var slot = out.indexOf(null); if (slot < 0) break;
      out[slot] = c; used[c.name] = 1; if (c.attribute) have[c.attribute] = (have[c.attribute] || 0) + 1;
      if (c._category === 'item_permanent') permN++; needCount--;
    }
  }
  for (var attr in req) { var remain = req[attr] - (have[attr] || 0); if (remain > 0) fill(attr, remain); }
  fill(null, out.filter(function (c) { return !c; }).length); // 灵活位/补满
  return out;
}

// 按流派智能构筑：队长=流派核心，队员优先combo，道具优先点名/流派/评分并兼顾费用曲线
function buildSmartDeck(arch) {
  var chars = allCards.filter(function(c) { return c._category === 'characters'; });
  // 队长：流派契合优先，评分次之
  var captain = chars.slice().map(function(c) {
    return { c: c, fit: (archOf(c, arch) ? 2 : 0) + cScore(c) / 10 };
  }).sort(function(a, b) { return b.fit - a.fit; })[0].c;
  // 队员：队长 recommended_with 点名 > 同流派 > sp_member > 评分
  var rec = captain.recommended_with || [];
  var memberRank = chars.filter(function(c) { return c !== captain; }).map(function(c) {
    var ms = cScore(c) / 10;
    if (rec.some(function(r) { return nameHit(c.name, r); })) ms += 2;
    if (archOf(c, arch)) ms += 1.2;
    if (c.sp_member) ms += 0.3;
    return { c: c, s: ms };
  }).sort(function(a, b) { return b.s - a.s; });
  var members = memberRank.slice(0, 2).map(function(x) { return x.c; });
  var team = [captain].concat(members);
  var teamNames = team.map(function(c) { return c.name; });
  var recSet = {};
  team.forEach(function(c) { (c.recommended_with || []).forEach(function(r) { recSet[r] = true; }); });
  // 道具打分：角色点名 > 流派契合 > 属性同色 > 评分
  function itemScore(c) {
    var v = cScore(c);
    for (var r in recSet) if (nameHit(c.name, r)) v += 4;
    if (archOf(c, arch)) v += 2.5;
    if (team.some(function(t) { return t.attribute === c.attribute; })) v += 0.6;
    return v;
  }
  // 道具属性硬约束（对齐查询页规则）：2无序+每非混沌角色属性2、混沌留灵活位、永续≤2/不重复；与手动补全共用 autoFillItems
  var items = autoFillItems(team, [], itemScore);
  // 携带卡：必须属于所选角色；流派契合+评分；优先2攻2技，至少1攻击
  function belongs(c) { return cardBelongsToTeam(c, teamNames); }
  var carryPool = allCards.filter(function(c) {
    return (c._category === 'attack_cards' || c._category === 'skill_cards') && belongs(c);
  }).map(function(c) { return { c: c, s: cScore(c) + (archOf(c, arch) ? 2 : 0) }; })
    .sort(function(a, b) { return b.s - a.s; });
  var atks = carryPool.filter(function(x) { return x.c._category === 'attack_cards'; }).map(function(x){return x.c;});
  var skls = carryPool.filter(function(x) { return x.c._category === 'skill_cards'; }).map(function(x){return x.c;});
  var sel = [];
  function take(arr, n) { var k = 0; while (n > 0 && k < arr.length) { var c = arr[k++]; if (sel.indexOf(c) < 0) { sel.push(c); n--; } } }
  take(atks, 2); take(skls, 2);
  var rest = atks.concat(skls); var ri = 0;
  while (sel.length < 4 && ri < rest.length) { if (sel.indexOf(rest[ri]) < 0) sel.push(rest[ri]); ri++; }
  return { chars: team, items: items, carries: sel, arch: arch, captain: captain };
}
/* ============================================================
 * 卡对象身份（2026-09-15 修）：**每一份卡必须是自己那份对象**
 * ------------------------------------------------------------
 * 实测（`_relaytest/_probe_card_identity.js`）：`buildSmartDeck` 返回的对象 **12/12 直接就是
 * `window.cardData` 本体**，而 `applySmartDeck` 把它们**按引用**存进 `deckConfig` —— 于是
 *   · 两个座位可以共用同一张卡对象（写在上面的每局标志 `_aoiDiscountUsed` / `_fromDeck` /
 *     `_isCarry` / `_usedThisTurn` 会跨座位串味）；
 *   · 那些标志还会写回**全局卡表**（`window.cardData` / `allCards`）。
 * 修法：所有"把卡放进 deckConfig / 牌库"的地方都克隆。见《共用卡对象缺陷与修复方案.md》，
 *   回归由 `_relaytest/card_identity_test.js` 守住。
 * ============================================================ */
function __cloneDeckCard(c) { return c ? JSON.parse(JSON.stringify(c)) : null; }
/** 按槽位克隆成定长数组（保留中间空位、只补尾部 —— 与原来的 concat(fill(null)) 语义一致） */
function __cloneDeckSlots(arr, n) {
  var out = (arr || []).slice(0, n).map(__cloneDeckCard);
  while (out.length < n) out.push(null);
  return out;
}
function applySmartDeck(player, d, showMsg) {
  deckConfig[player].chars = __cloneDeckSlots(d.chars, 3);
  deckConfig[player].items = __cloneDeckSlots(d.items, 8);
  deckConfig[player].carries = __cloneDeckSlots(d.carries, 4);
  renderDeckSide(player);
  if (showMsg) {
    var msg = '已智能构筑【' + d.arch + '】\n队长（核心）：' + d.captain.name + '\n队员：' + d.chars.slice(1).map(function(c){return c.name;}).join('、') +
      '\n道具' + d.items.length + '张（优先队长combo与同流派）\n携带' + d.carries.length + '张';
    showToast(msg, 'info');
  }
}
// 随机配置：随机选一个流派后智能构筑
function randomDeck(player) {
  var arch = ARCH_LIST[Math.floor(Math.random() * ARCH_LIST.length)];
  applySmartDeck(player, buildSmartDeck(arch), true);
}
// 推荐构筑：玩家指定流派
function recommendDeck(player) {
  showChoiceModal('智能推荐构筑', '流派', '选择要构筑的流派：队长由流派核心担任，道具优先角色combo与同流派、兼顾费用曲线', ARCH_LIST.slice(), function(idx) {
    if (idx === null || idx === undefined || idx < 0) return;
    applySmartDeck(player, buildSmartDeck(ARCH_LIST[idx]), true);
  });
}
// ========== 构筑校验 + 卡组码 ==========
function nonNull(a){ return (a||[]).filter(function(c){return c!==null && !!c;}); }
function carryBelongs(c, names){ return cardBelongsToTeam(c, names); }
// 返回问题数组（空数组合法）
function validateDeck(player) {
  var cfg = deckConfig[player], errs = [];
  var chars = nonNull(cfg.chars), items = nonNull(cfg.items), carries = nonNull(cfg.carries);
  if (chars.length !== 3) errs.push('角色需恰好3张（当前'+chars.length+'）');
  if (items.length !== 8) errs.push('道具需恰好8张（当前'+items.length+'）');
  if (carries.length !== 4) errs.push('携带卡需恰好4张（当前'+carries.length+'）');
  var cn = {}; chars.forEach(function(c){ cn[c.name]=(cn[c.name]||0)+1; });
  Object.keys(cn).forEach(function(n){ if (cn[n]>1) errs.push('角色重复：'+n); });
  var names = chars.map(function(c){return c.name;});
  carries.forEach(function(c){ if (!carryBelongs(c, names)) errs.push('携带卡【'+c.name+'】不属于所选的3名角色（同名不同形态不通用）'); });
  var inm={}; items.forEach(function(c){inm[c.name]=(inm[c.name]||0)+1;});
  Object.keys(inm).forEach(function(n){ if(inm[n]>1) errs.push('同名道具不能重复：'+n); });
  var permN=items.filter(function(c){return c._category==='item_permanent';}).length;
  if(permN>2) errs.push('永续道具最多2张（当前'+permN+'张）');
  // 道具属性配额：默认2无序 + 每名非混沌角色对应属性2张；混沌角色可带任意属性(灵活位)
  var attrNeed={'无序':2};
  chars.forEach(function(c){ if(c.attribute && c.attribute!=='混沌') attrNeed[c.attribute]=(attrNeed[c.attribute]||0)+2; });
  var attrHave={};
  /* 【2026-10-07】道具的属性配额统计改走 __ruleAttrOf：
     卡面写"在规则上还能当作 X 属性使用"的卡（镌刻的艺术 ⇒ 无序）在**卡组构建**里也算那个属性
     （作者 2026-10-07 明确：构建与效果判定都管）。 */
  items.forEach(function(c){ var a=(typeof __ruleAttrOf==='function')?__ruleAttrOf(c):(c.attribute||''); if(a) attrHave[a]=(attrHave[a]||0)+1; });
  Object.keys(attrNeed).forEach(function(a){
    if((attrHave[a]||0)<attrNeed[a]) errs.push('【'+a+'】属性道具不足：需要'+attrNeed[a]+'张，当前'+(attrHave[a]||0)+'张（规则：2无序+每名非混沌角色对应属性2张，混沌角色为灵活位）');
  });
  var cnm={}; carries.forEach(function(c){cnm[c.name]=(cnm[c.name]||0)+1;});
  Object.keys(cnm).forEach(function(n){ if(cnm[n]>1) errs.push('同名携带卡不能重复：'+n); });
  return errs;
}
function exportDeckCode(player) {
  player = (player === 'p2') ? 'p2' : 'p1';
  var errs = validateDeck(player);
  if (errs.length) { showToast('卡组不合法，无法导出：\n'+errs.join('\n'), 'warn'); return; }
  function pick(k){ return deckConfig[player][k].filter(Boolean).map(function(c){return c.name;}); }
  var obj = { v:1, c:pick('chars'), i:pick('items'), k:pick('carries') };
  var code = 'RJZ' + btoa(unescape(encodeURIComponent(JSON.stringify(obj))));
  window.prompt((player === 'p1' ? '你的' : 'AI 的') + '卡组码已生成（Ctrl+C 复制保存）：', code);
}
function importDeckCode(player) {
  player = (player === 'p2') ? 'p2' : 'p1';
  var raw = window.prompt('粘贴' + (player === 'p1' ? '你的' : 'AI 的') + '卡组码：'); if (!raw) return;
  var obj;
  try { obj = JSON.parse(decodeURIComponent(escape(atob(raw.trim().replace(/^RJZ/,''))))); }
  catch(e) { showToast('卡组码解析失败，请检查是否完整复制', 'warn'); return; }
  function byName(nm){ return allCards.find(function(c){return c.name===nm;}) || null; }
  var ch=(obj.c||[]).map(byName), it=(obj.i||[]).map(byName), ck=(obj.k||[]).map(byName);
  var miss=[];
  function missCheck(src,got){ src.forEach(function(n,i){ if(!got[i]) miss.push(n); }); }
  missCheck(obj.c||[],ch); missCheck(obj.i||[],it); missCheck(obj.k||[],ck);
  deckConfig[player].chars = ch.concat(Array(Math.max(0,3-ch.length)).fill(null)).slice(0,3);
  deckConfig[player].items = it.concat(Array(Math.max(0,8-it.length)).fill(null)).slice(0,8);
  deckConfig[player].carries = ck.concat(Array(Math.max(0,4-ck.length)).fill(null)).slice(0,4);
  renderDeckSide(player);
  saveDeckConfig();
  var __ve = validateDeck(player);
  var __head = miss.length ? ('以下卡未在卡库找到（已留空，请手动补全）：\n'+miss.join('、')) : ((player === 'p1' ? '你的' : 'AI 的') + '卡组导入成功');
  showToast(__head + (__ve.length ? ('\n\n⚠ 当前卡组不合法（开战前请修正）：\n'+__ve.join('\n')) : ''));
}

// ========== 对战 ==========
var __pendingSandbox = false;   // 【测试卡组·沙盒】由菜单按钮置位，startTurn 首次进入时落到 battleState._sandbox
function startBattle(__sandbox) {
  /* 【2026-10-03】进对局起播 BGM：**延后一拍**，等战斗状态（同步值/上限）初始化完再判断，
     避免开局读到未初始化的数值而误播残血曲（作者实测："一开局就放"）。 */
  try { setTimeout(function () { try { if (typeof __sfx !== 'undefined' && __sfx.bgmStart) __sfx.bgmStart(); } catch (e) {} }, 400); } catch (e) {}
  __pendingSandbox = !!__sandbox;   // 不包 try（审计：不得新增静默吞；这行也不可能抛）
  /* ⚠ 这里**必须**区分单机与联机（作者 2026-09-16 报："联机对战使用的卡组还是单机对战的卡组"）：
     联机房主开局走的也是 startBattle()（见 Online._onGameStart 里的 startBattle() 调用），
     而本函数第一行就会 setDeckMode('pve') 把卡组切到"单机 vs AI"那一套 ——
     于是联机对局里房主用的是自己上一次编辑的单机卡组（客人不受影响：客人不发牌组、等快照）。
     修法：只有**不在联机对局中**时才切单机卡组。 */
  var __inOnlineMatch = false;
  try { __inOnlineMatch = !!(typeof Online !== 'undefined' && Online && Online.active && Online._startingOnlineBattle); } catch (e) {}
  if (!__inOnlineMatch) { try { setDeckMode('pve', true); } catch (e) {} }
  // 检查双方卡组是否完整
  for (var player of playerIds()) {
    var config = deckConfig[player];
    var charCount = config.chars.filter(function(c) { return c !== null; }).length;
    var itemCount = config.items.filter(function(c) { return c !== null; }).length;
    var carryCount = config.carries.filter(function(c) { return c !== null; }).length;
    
    var errs = validateDeck(player);
    if (errs.length) {
      showToast((player === 'p1' ? '玩家1' : 'AI') + '卡组不合法：\n' + errs.join('\n'), 'warn');
      showScreen('deckBuilder');
      return;
    }
  }
  
  showScreen('battleScreen');
  initBattle();
}

// ===== 肉鸽模式 =====
var roguelikeState = null;


/* ===== 肉鸽入口 / 三选一开局 / 存档（作者 2026-10 设想）===== */
var RL_SAVE_KEY = 'rujuzhe_rogue_save_v1';

function rlSaveGame() {
  try { localStorage.setItem(RL_SAVE_KEY, JSON.stringify(roguelikeState)); } catch (e) {}
}
function rlHasSave() {
  try { return !!localStorage.getItem(RL_SAVE_KEY); } catch (e) { return false; }
}
function rlCarryPool() {
  var r = (typeof window !== 'undefined' && window.rogueCardData) ? window.rogueCardData : null;
  return r ? (r.attacks || []).concat(r.skills || []) : [];
}
function rlEl(id, cls, parent) {
  var e = document.getElementById(id);
  if (!e) {
    e = document.createElement('div');
    e.id = id;
    if (cls) e.className = cls;
    (parent || document.body).appendChild(e);
  }
  return e;
}
function rlHide(id) { var e = document.getElementById(id); if (e) e.style.display = 'none'; }

/* —— 入口页：开始新游戏 / 继续上一次 —— */
function startRoguelike() {
  roguelikeState = null;
  var el = rlEl('rogueEntry', 'rl-entry-screen');
  el.innerHTML = '<div class="rl-entry-wrap">'
    + '<h1>入局者 · 肉鸽模式</h1>'
    + '<p class="rl-entry-sub">选择角色的被动与 SP，一路清空 5 层节点</p>'
    + '<div class="rl-entry-btns">'
    + '<button class="rl-entry-btn primary" onclick="rlEntryNew()">🗡️ 开始新游戏</button>'
    + '<button class="rl-entry-btn" id="rlEntryContinue" onclick="rlEntryContinue()">📖 继续上一次的游戏</button>'
    + '</div>'
    + '<div class="rl-entry-tip" id="rlEntryTip"></div>'
    + '</div>';
  var c = document.getElementById('rlEntryContinue');
  if (c && !rlHasSave()) { c.disabled = true; c.textContent = '📖 继续上一次的游戏（暂无存档）'; }
  el.style.display = 'flex';
}
function rlEntryNew() {
  rlHide('rogueEntry');
  rlNewGame();
}
function rlEntryContinue() {
  var raw = null;
  try { raw = localStorage.getItem(RL_SAVE_KEY); } catch (e) {}
  if (!raw) { if (typeof showToast === 'function') showToast('没有可继续的存档', 'warn'); return; }
  try { roguelikeState = JSON.parse(raw); } catch (e) {
    if (typeof showToast === 'function') showToast('存档读取失败', 'warn'); return;
  }
  rlHide('rogueEntry');
  showScreen('roguelikeMap');
  renderRoguelikeMap();
  if (typeof showToast === 'function') showToast('已读取存档：第 ' + roguelikeState.floor + ' 层', 'good');
}

/* —— 开局三选一：1 角色 + 4 随机道具 —— */
function rlShowStarterPick() {
  var s = roguelikeState;
  var el = rlEl('roguePick', 'rl-entry-screen');
  var cards = (s.starters || []).map(function (g, i) {
    return '<div class="rl-pick-card" onclick="rlPickStarter(' + i + ')">'
      + '<div class="rl-pick-char"><span class="rl-pick-name">' + g.char.name + '</span>'
      + '<span class="rl-pick-meta">同步 ' + (g.char.sync || '') + ' · ' + (g.char.tags || '') + '</span></div>'
      + '<div class="rl-pick-passive">' + String(g.char.passive || '').slice(0, 90) + '…</div>'
      + '<div class="rl-pick-items">' + g.items.map(function (c) {
          return '<span class="rl-pick-item">' + c.name + '</span>'; }).join('') + '</div>'
      + '</div>';
  }).join('');
  el.innerHTML = '<div class="rl-entry-wrap wide"><h1>选择你的开局</h1>'
    + '<p class="rl-entry-sub">每组 ＝ 1 张角色卡 ＋ 4 张随机道具卡（角色自带其攻击卡与技能卡）</p>'
    + '<div class="rl-pick-row">' + cards + '</div></div>';
  el.style.display = 'flex';
}
function rlPickStarter(i) {
  var s = roguelikeState;
  var g = (s.starters || [])[i];
  if (!g) return;
  var clone = function (o) { return JSON.parse(JSON.stringify(o)); };
  s.deck.chars = [clone(g.char)];
  s.deck.items = g.items.map(clone);
  s.deck.carries = __rlCarriesOf(g.char, rlCarryPool()).map(clone);
  s.battleDeck = { chars: s.deck.chars.map(clone), items: s.deck.items.map(clone), carries: s.deck.carries.map(clone) };
  s.starters = null;
  rlHide('roguePick');
  generateRoguelikeMap();
  showScreen('roguelikeMap');
  renderRoguelikeMap();
  rlSaveGame();
  if (typeof showToast === 'function') {
    showToast('开局：' + g.char.name + '（携带卡 ' + s.deck.carries.length + ' 张）', 'good');
  }
}

/* —— 左下角：背包 / 卡组编组 —— */
function rlRenderDeckBar() {
  var bar = rlEl('rlDeckBar', 'rl-deck-bar');
  bar.innerHTML = '<button class="rl-deck-btn" onclick="openRogueDeck(\'battle\')">🃏 卡组编组</button>'
                + '<button class="rl-deck-btn" onclick="openRogueDeck(\'bag\')">🎒 背包</button>';
  bar.style.display = 'flex';
}
function rlHideDeckBar() { var b = document.getElementById('rlDeckBar'); if (b) b.style.display = 'none'; }

/* ===== 肉鸽扩展（作者 2026-10）：角色技能 / 队伍 buff / 背包编组 / 召唤物 UI =====
   肉鸽是纯回合制：这里没有时点与连锁，只有「结算点触发」。
   规则：非 SP 技能一队只生效一个（取前排第一位）；SP 按效果类型去重，同类型只生效一个。 */

/* 角色技能表（键＝肉鸽角色卡文件名去 .png）。n=非 SP，s=SP。
   字段：trig=passive/battleStart/turnStart/afterCard/afterDamage/afterJudge，
        need=条件（属性名 / sameAttr / carry），其余为数值增量。 */
var RL_CHAR_FX = {
  'XHZD':        { n: { trig: 'afterCard', need: '无序', atk: 1 },                 s: { t: 'atk', v: 2 } },
  '冬马':         { n: { trig: 'passive', execLowSync: 50 },                        s: { t: 'critRate', v: 25 } },
  '枫（水着）':    { n: { trig: 'afterDamage', need: '理智', elem: { '理智': 1 } },   s: { t: 'refillMul', v: 50 } },
  '枫':           { n: { trig: 'afterCard', need: 'sameAttr', draw: 1 },            s: { t: 'startDraw', v: 2, startCost: 4 } },
  '光太郎':       { n: { trig: 'battleStart', initHand: 1, extraDraw: 1 },          s: { t: 'sacrifice', v: 1 } },
  '惠':           { n: { trig: 'passive', firstUseMinus: 1 },                       s: { t: 'refillMul', v: 50 } },
  '结衣':         { n: { trig: 'afterDamage', need: '热忱', elemMul: { '热忱': 50 }, heal: 4 }, s: { t: 'atk', v: 3 } },
  '葵':           { n: { trig: 'passive', firstUseMinus: 1 },                       s: { t: 'refillMul', v: 50, critRate: 25 } },
  '里尔亚斯':      { n: { trig: 'battleStart', atk: 2 },                            s: { t: 'extraDraw', v: 1 } },
  '里绪（水着）':   { n: { trig: 'passive', firstCrit: 1, critDmg: 50 },              s: { t: 'critDmg', v: 25 } },
  '里绪':         { n: { trig: 'turnStart', judgeDmg: '1d4' },                      s: { t: 'judge', v: 1 } },
  '莉莉':         { n: { trig: 'passive' },                                        s: { t: 'critRate', v: 25 } },
  '琉璃（水着）':   { n: { trig: 'afterCard', need: 'carry', cost: 3 },               s: { t: 'elem', elem: { '热忱': 3 } } },
  '琉璃(万圣祭）':  { n: { trig: 'passive', final: 1, atk: 1 },                      s: { t: 'final', v: 1 } },
  '琉璃':         { n: { trig: 'afterJudge', cost: 2 },                            s: { t: 'afterJudgeDraw', v: 2 } },
  '露璐缇雅':      { n: { trig: 'turnStart', syncCost: 3, draw: 1 },                 s: { t: 'extraDraw', v: 1 } },
  '霞':           { n: { trig: 'turnStart', draw: 1 },                             s: { t: 'none' } },
  '小春':         { n: { trig: 'turnStart', cost: 1 },                             s: { t: 'initHand', v: 2 } },
  '伊织':         { n: { trig: 'afterCard', draw: 1, cost: 1 },                    s: { t: 'final', v: 1 } },
  '樱子':         { n: { trig: 'turnStart', firstUseMinus: 1 },                    s: { t: 'atk', v: 1, elem: { '热忱': 2, '理智': 2, '混沌': 2, '无序': 2 } } },
  '予（水着）':    { n: { trig: 'afterCard', need: '战术', dmg: 2, dmgElem: '理智' }, s: { t: 'coin', v: 2 } },
  '予':           { n: { trig: 'turnStart', attrBuff: 1 },                         s: { t: 'judge', v: 1 } }
};

var RL_BUFF_KEYS = ['atk', 'critRate', 'critDmg', 'refillMul', 'judge', 'final', 'startDraw',
                    'startCost', 'extraDraw', 'initHand', 'firstUseMinus', 'sacrifice',
                    'execLowSync', 'firstCrit', 'afterJudgeDraw'];

function rlNewBuff() {
  var b = { elem: {}, elemMul: {} };
  RL_BUFF_KEYS.forEach(function (k) { b[k] = 0; });
  return b;
}
function rlFxInto(b, d) {
  if (!d) return;
  RL_BUFF_KEYS.forEach(function (k) { if (d[k]) b[k] += d[k]; });
  if (d.t && d.v && RL_BUFF_KEYS.indexOf(d.t) >= 0) b[d.t] += d.v;   // SP 形式：{t:'atk', v:2}
  if (d.elem) { for (var k1 in d.elem) b.elem[k1] = (b.elem[k1] || 0) + d.elem[k1]; }
  if (d.elemMul) { for (var k2 in d.elemMul) b.elemMul[k2] = (b.elemMul[k2] || 0) + d.elemMul[k2]; }
}

/* 组装队伍 buff：非 SP 只取前排第一位；SP 同类型只生效一个 */
function rlApplyTeamBuffs(p) {
  var b = rlNewBuff();
  p.b = b;
  var spTypes = {};
  (p.units || []).forEach(function (u, idx) {
    var fx = RL_CHAR_FX[u.key];
    if (!fx) return;
    if (idx === 0 && fx.n && fx.n.trig === 'passive') rlFxInto(b, fx.n);
    if (fx.s && fx.s.t && !spTypes[fx.s.t]) { spTypes[fx.s.t] = 1; rlFxInto(b, fx.s); }
  });
  return b;
}

/* 结算点触发器（只有非 SP 技能，且只有前排第一位会触发） */
function rlCharHook(trig, info) {
  if (!rlState || !rlState.p1) return;
  var p = rlState.p1;
  if (!p.units || !p.units.length) return;
  var fx = RL_CHAR_FX[p.units[0].key];
  if (!fx || !fx.n || fx.n.trig !== trig) return;
  var n = fx.n; info = info || {};
  if (n.need) {
    if (n.need === 'sameAttr' && !info.sameAttr) return;
    if (n.need === 'carry' && !info.isCarry) return;
    if (n.need !== 'sameAttr' && n.need !== 'carry' && info.attr !== n.need) return;
  }
  if (!p.b) p.b = rlNewBuff();
  if (n.atk) p.b.atk += n.atk;
  if (n.cost) p.cost = Math.min(p.maxCost, p.cost + n.cost);
  if (n.draw) { for (var i = 0; i < n.draw; i++) rlDrawCard('p1'); }
  if (n.heal) p.sync = Math.min(p.maxSync, p.sync + n.heal);
  if (n.syncCost) { p.sync = Math.max(0, p.sync - n.syncCost); rlDamageSide(rlState.p2, 0); }
  if (n.dmg) rlDamageSide(rlState.p2, n.dmg);
  if (n.judgeDmg) rlDamageSide(rlState.p2, rlRollDice(n.judgeDmg));
  if (n.elem) { for (var k in n.elem) p.b.elem[k] = (p.b.elem[k] || 0) + n.elem[k]; }
  rlRenderUI();
}

/* ===== 背包 / 出战编组界面（战斗外） ===== */
var RL_DECK_CAP = { chars: 3, items: 8, carries: 4 };
var RL_DECK_LABEL = { chars: '角色', items: '道具', carries: '携带' };

function rlDeckBucket() { return ['chars', 'items', 'carries']; }
function rlInBattle(kind, card) {
  return (roguelikeState.battleDeck[kind] || []).some(function (c) { return c.file === card.file; });
}
function openRogueDeck() {
  if (!roguelikeState) return;
  var el = document.getElementById('rogueDeckScreen');
  if (!el) {
    el = document.createElement('div');
    el.id = 'rogueDeckScreen';
    el.className = 'rl-deck-screen';
    el.innerHTML = '<div class="rl-deck-wrap">'
      + '<div class="rl-deck-head"><h2>🎒 背包 / 出战编组</h2>'
      + '<button class="rl-deck-close" onclick="closeRogueDeck()">✕ 返回地图</button></div>'
      + '<div class="rl-deck-hint">点卡牌即可在「出战」与「背包」之间切换　·　出战上限：角色 3 / 道具 8 / 携带 4</div>'
      + '<div class="rl-deck-cols">'
      + '<div class="rl-deck-col"><h3>出战编组</h3><div id="rlBattleCol" class="rl-deck-list"></div></div>'
      + '<div class="rl-deck-col"><h3>背包（收藏）</h3><div id="rlBagCol" class="rl-deck-list"></div></div>'
      + '</div>'
      + '<div class="rl-deck-foot"><button class="rl-deck-auto" onclick="rlAutoDeck()">✨ 一键推荐编组</button>'
      + '<span id="rlDeckMsg" class="rl-deck-msg"></span></div>'
      + '</div>';
    document.body.appendChild(el);
  }
  renderRogueDeck();
  el.style.display = 'flex';
}
function closeRogueDeck() {
  var el = document.getElementById('rogueDeckScreen');
  if (el) el.style.display = 'none';
  renderRoguelikeMap();
}
function rlCardChip(kind, card, inBattle) {
  var cls = 'rl-chip' + (inBattle ? ' on' : '');
  var extra = (kind === 'chars') ? ('同步 ' + (card.sync || '') )
            : (card.cost !== undefined && card.cost !== '' ? (card.cost + ' 费') : '');
  var tag = card.attribute || card.type || '';
  return '<div class="' + cls + '" onclick="rlToggleCard(\'' + kind + '\',\'' +
         encodeURIComponent(card.file) + '\')" title="' + (card.text || card.passive || '') + '">'
       + '<span class="rl-chip-name">' + card.name + '</span>'
       + '<span class="rl-chip-meta">' + [extra, tag].filter(Boolean).join(' · ') + '</span>'
       + '</div>';
}

function rlToggleCard(kind, fileEnc) {
  var file = decodeURIComponent(fileEnc);
  var bagArr = roguelikeState.deck[kind] || [], batArr = roguelikeState.battleDeck[kind] || [];
  var inBat = batArr.filter(function (c) { return c.file === file; })[0];
  var msg = document.getElementById('rlDeckMsg');
  if (inBat) {
    roguelikeState.battleDeck[kind] = batArr.filter(function (c) { return c.file !== file; });
    if (msg) msg.textContent = '已移回背包：' + inBat.name;
  } else {
    if (batArr.length >= RL_DECK_CAP[kind]) { if (msg) msg.textContent = '⚠ ' + RL_DECK_LABEL[kind] + '最多 ' + RL_DECK_CAP[kind] + ' 张'; return; }
    var card = bagArr.filter(function (c) { return c.file === file; })[0];
    if (!card) return;
    batArr.push(card);
    roguelikeState.battleDeck[kind] = batArr;
    if (msg) msg.textContent = '已加入出战：' + card.name;
  }
  renderRogueDeck();
}
function rlAutoDeck() {
  if (!roguelikeState) return;
  ['chars', 'items', 'carries'].forEach(function (kind) {
    roguelikeState.battleDeck[kind] = (roguelikeState.deck[kind] || []).slice(0, RL_DECK_CAP[kind]);
  });
  var msg = document.getElementById('rlDeckMsg');
  if (msg) msg.textContent = '已按背包顺序自动编组（可再点卡调整）';
  renderRogueDeck();
}


/* 取某角色的携带卡（攻击卡 + 技能卡）：按 character_full / character 精确匹配，禁止模糊匹配 */
function __rlCarriesOf(ch, pool) {
  if (!ch) return [];
  var full = ch.name || '';
  var short = full.split('·')[0].split('（')[0];
  return (pool || []).filter(function(c) {
    return c.character_full === full || c.character === full || c.character === short;
  });
}

function rlNewGame() {
  // 初始化肉鸽状态（由入口页「开始新游戏」调用）
  roguelikeState = {
    floor: 1,
    gold: 0,
    level: 1,
    motivation: 0,
    deck: { chars: [], items: [], carries: [] },
    map: [],
    currentLayer: 0,
    rewardPhase: null, // 'levelup' | 'char' | 'item' | null
    pendingRewards: []
  };
  
  // 卡池：优先用肉鸽专属卡池（数据块直接赋到 window.rogueCardData），没有才退回原版 cardData
  var __rcd = (typeof window !== 'undefined' && window.rogueCardData) ? window.rogueCardData : null;
  var allChars = __rcd ? __rcd.chars
    : ((window.cardData && window.cardData.characters) ? window.cardData.characters : []);
  var allItemsRaw = __rcd ? __rcd.items
    : ((window.cardData && window.cardData.item_single) ? window.cardData.item_single.concat(window.cardData.item_permanent || []) : []);
  var allCarries = __rcd ? (__rcd.attacks || []).concat(__rcd.skills || [])
    : ((window.cardData && window.cardData.attack_cards) ? window.cardData.attack_cards.concat(window.cardData.skill_cards || []) : []);

  // 肉鸽卡池已按作者文本定制过，不再过滤；只有退回原版卡池时才做移动/投掷过滤
  var allItems = allItemsRaw;
  if (!__rcd) {
    var moveThrowKeywords = ['移动', '位移', '投掷', '掷骰', '骰子', '前进', '后退', '格', '打断', '方向', 'Again'];
    allItems = allItemsRaw.filter(function(c) {
      var eff = (c.effect || '') + (c.name || '');
      for (var k = 0; k < moveThrowKeywords.length; k++) {
        if (eff.indexOf(moveThrowKeywords[k]) >= 0) return false;
      }
      return true;
    });
    if (allItems.length < 8) allItems = allItemsRaw;
  }
  
  shuffleArray(allChars);
  shuffleArray(allItems);
  shuffleArray(allCarries);
  
  // 开局三选一（作者 2026-10 设想）：每组 ＝ 1 张角色卡 ＋ 4 张随机道具卡，
  // 并且**每组至少保证 1 张能造成伤害的道具卡**（免得开局四张全是辅助卡打不动）
  var __clone = function (o) { return JSON.parse(JSON.stringify(o)); };
  var __isDmg = function (c) {
    return (c.type === '侵略') || /造成[\s\S]{0,14}伤害/.test((c.effect || '') + (c.text || ''));
  };
  var __dmgPool = allItems.filter(__isDmg);
  var __othPool = allItems.filter(function (c) { return !__isDmg(c); });
  roguelikeState.starters = [];
  for (var __si = 0; __si < 3 && __si < allChars.length; __si++) {
    var __grp = [];
    if (__dmgPool.length) __grp.push(__clone(__dmgPool[__si % __dmgPool.length]));
    for (var __k = 0; __grp.length < 4 && __k < __othPool.length; __k++) {
      var __cand = __othPool[(__si * 3 + __k) % __othPool.length];
      var __dup = false;
      for (var __j = 0; __j < __grp.length; __j++) { if (__grp[__j].file === __cand.file) __dup = true; }
      if (!__dup) __grp.push(__clone(__cand));
    }
    roguelikeState.starters.push({ char: __clone(allChars[__si]), items: __grp });
  }
  
  rlShowStarterPick();
  return;
}

function generateRoguelikeMap() {
  // 生成5层地图，每层2-3个节点
  var map = [];
  var nodeTypes = ['battle', 'battle', 'shop', 'event', 'rest'];
  var totalLayers = 5;
  
  for (var layer = 0; layer < totalLayers; layer++) {
    var nodeCount = (layer === totalLayers - 1) ? 1 : (Math.random() < 0.5 ? 2 : 3);
    var nodes = [];
    for (var n = 0; n < nodeCount; n++) {
      var type;
      if (layer === totalLayers - 1) {
        type = 'boss';
      } else if (layer === 0) {
        type = 'battle';
      } else {
        type = nodeTypes[Math.floor(Math.random() * nodeTypes.length)];
      }
      nodes.push({ type: type, completed: false, id: layer + '_' + n });
    }
    map.push(nodes);
  }
  roguelikeState.map = map;
  roguelikeState.currentLayer = 0;
}



function selectRoguelikeNode(layer, index) {
  if (!roguelikeState || layer !== roguelikeState.currentLayer) return;
  var node = roguelikeState.map[layer][index];
  
  if (node.type === 'battle' || node.type === 'boss') {
    startRoguelikeBattle(node);
  } else if (node.type === 'shop') {
    // 商店：花费金币购买卡牌
    var cost = 500;
    if (roguelikeState.gold >= cost) {
      if (confirm('商店：花费' + cost + '金币购买一张随机道具卡？')) {
        roguelikeState.gold -= cost;
        var allItems = (window.cardData && window.cardData.item_single) ? window.cardData.item_single.concat(window.cardData.item_permanent || []) : [];
        var newItem = JSON.parse(JSON.stringify(allItems[Math.floor(Math.random() * allItems.length)]));
        roguelikeState.deck.items.push(newItem);
        showToast('获得道具卡：' + newItem.name, 'good');
        completeNode(layer, index);
      }
    } else {
      showToast('金币不足！需要' + cost + '金币，当前' + roguelikeState.gold + '金币', 'warn');
    }
  } else if (node.type === 'event') {
    // 事件：随机效果
    var events = [
      { text: '发现宝箱！获得300金币', effect: function() { roguelikeState.gold += 300; } },
      { text: '神秘旅人赠予你1点激励点数', effect: function() { roguelikeState.motivation += 1; checkRoguelikeLevelUp(); } },
      { text: '恢复全部同步值', effect: function() { /* 战斗时生效 */ } }
    ];
    var evt = events[Math.floor(Math.random() * events.length)];
    showToast('事件：' + evt.text, 'info');
    evt.effect();
    completeNode(layer, index);
  } else if (node.type === 'rest') {
    // 休息：升级或回血
    if (confirm('休息点：获得1点激励点数？')) {
      roguelikeState.motivation += 1;
      checkRoguelikeLevelUp();
    }
    completeNode(layer, index);
  }
}

function completeNode(layer, index) {
  roguelikeState.map[layer][index].completed = true;
  rlSaveGame();
  roguelikeState.currentLayer++;
  
  if (roguelikeState.currentLayer >= roguelikeState.map.length) {
    // 通关当前层地图，进入下一层
    roguelikeState.floor++;
    if (roguelikeState.floor > 10) {
      showToast('🎉 恭喜通关肉鸽模式！\n最终层数：' + roguelikeState.floor + '\n金币：' + roguelikeState.gold, 'good');
      showScreen('mainMenu');
      return;
    }
    generateRoguelikeMap();
  }
  renderRoguelikeMap();
}

function checkRoguelikeLevelUp() {
  while (roguelikeState.level < 10) {
    var cost = roguelikeState.level < 5 ? roguelikeState.level : 7;
    if (roguelikeState.motivation >= cost) {
      roguelikeState.motivation -= cost;
      roguelikeState.level++;
      showToast('升级！当前等级 Lv' + roguelikeState.level, 'good');
    } else break;
  }
}


// ===== 肉鸽对战核心逻辑 =====
var rlState = null;

function rlInitBattle() {
  if (!roguelikeState) return;      // 还没选完开局时不会被调用，防御一下
  // 初始化战斗状态（出战编组优先；没有编组时退回背包）
  var __bd = roguelikeState.battleDeck || roguelikeState.deck;
  var p1Chars = __bd.chars;
  var p1Items = __bd.items.slice();
  var p1Carries = __bd.carries.slice();
  
  // 补齐卡组
  var allItems = (window.cardData && window.cardData.item_single) ? window.cardData.item_single.concat(window.cardData.item_permanent || []) : [];
  allItems = allItems.filter(function(c) {
    var eff = (c.effect || '') + (c.name || '');
    var kws = ['移动','位移','投掷','掷骰','骰子','前进','后退','格','打断','方向','Again'];
    for (var k=0;k<kws.length;k++) if (eff.indexOf(kws[k])>=0) return false;
    return true;
  });
  shuffleArray(allItems);
  // 不再自动补齐：牌组 = 出战编组原样（开局 4 道具 + 该角色的攻击/技能卡），
  // 想加卡就去打奖励 / 商店，再到左下角「卡组编组」里挑（作者 2026-10 口径）

  var allCarries = (window.cardData && window.cardData.attack_cards) ? window.cardData.attack_cards.concat(window.cardData.skill_cards || []) : [];
  shuffleArray(allCarries);
  
  // 构建玩家牌组
  var p1Deck = [];
  for (var i=0;i<p1Items.length;i++) p1Deck.push(JSON.parse(JSON.stringify(p1Items[i])));
  for (var i=0;i<p1Carries.length;i++) p1Deck.push(JSON.parse(JSON.stringify(p1Carries[i])));
  shuffleArray(p1Deck);
  
  // 队伍同步值：出战角色同步值之和 × 2.5（向上取整，作者口径）
  var __rlMaxSync = Math.ceil(p1Chars.reduce(function(s,c){return s+(c.sync||5);},0) * 2.5);

  // 敌人（根据层数生成）
  var enemyChars = (window.cardData && window.cardData.characters) ? window.cardData.characters.slice() : [];
  shuffleArray(enemyChars);
  var enemy = enemyChars[0];
  var enemySync = (enemy.sync || 5) * 2 + roguelikeState.floor * 3;
  
  var enemyDeck = [];
  var enemyItems = allItems.slice();
  shuffleArray(enemyItems);
  for (var i=0;i<6;i++) enemyDeck.push(JSON.parse(JSON.stringify(enemyItems[i])));
  
  rlState = {
    turn: 1,
    phase: 'prepare', // prepare, main, end
    currentPlayer: 'p1',
    p1: {
      chars: p1Chars,
      leader: p1Chars[0],
      sync: __rlMaxSync,
      maxSync: __rlMaxSync,
      fascination: 6,
      cost: 0,
      maxCost: 12,
      deck: p1Deck,
      hand: [],
      grave: [],
      removed: [],
      permanent: [],
      attackBuff: 0,
      shield: 0
    },
    p2: {
      chars: [enemy],
      leader: enemy,
      sync: enemySync,
      maxSync: enemySync,
      fascination: 6,
      cost: 0,
      maxCost: 10,
      deck: enemyDeck,
      hand: [],
      grave: [],
      permanent: [],
      attackBuff: 0,
      shield: 0,
      intent: null
    }
  };
  
  // 布阵前排：每名出战角色各自一份同步值（= sync × 2.5 向上取整），队伍同步值 = 各角色之和
  rlState.p1.units = p1Chars.map(function (c) {
    var hp = Math.ceil((c.sync || 5) * 2.5);
    return { name: c.name, full: c.name, sync: hp, maxSync: hp, alive: true };
  });
  if (rlState.p1.units.length) rlState.p1.units[0].isLeader = true;
  rlState.p1.summons = [];
  rlState.p1.maxSync = rlState.p1.sync = rlSumSync(rlState.p1);

  // 背包被动（存在于背包中即生效）
  rlApplyBackpack(rlState.p1);
  rlApplyBackpack(rlState.p2);

  // 角色技能 → 队伍 buff（非 SP 只取前排第一位；SP 同类型只生效一个）
  rlApplyTeamBuffs(rlState.p1);
  var __b0 = rlState.p1.b || {};
  rlState.p1.cost = Math.min(rlState.p1.maxCost, rlState.p1.cost + (__b0.startCost || 0));

  // 初始抽牌（含角色技能的初始手牌/开局抽卡加成）
  for (var i=0;i<4 + (__b0.initHand || 0);i++) rlDrawCard('p1');
  for (var i=0;i<(__b0.startDraw || 0);i++) rlDrawCard('p1');
  for (var i=0;i<4;i++) rlDrawCard('p2');
  
  rlStartTurn('p1');
}

function rlDrawCard(player) {
  if (!rlState) return null;
  var p = rlState[player];
  if (p.deck.length === 0) {
    // 牌组空了，洗回墓地
    p.deck = p.grave.slice();
    p.grave = [];
    shuffleArray(p.deck);
  }
  if (p.deck.length === 0) return null;
  var card = p.deck.shift();
  if (p.hand.length < 7) {
    p.hand.push(card);
    return card;
  } else {
    p.grave.push(card);
    return null;
  }
}

/* ===== 布阵前排：每名出战角色各自一份同步值（作者 2026-10 规则）===== */
function rlSumSync(p) {
  return (p.units || []).reduce(function (s, u) { return s + Math.max(0, u.sync); }, 0);
}
function rlAliveUnit(p) {
  return (p.units || []).filter(function (u) { return u.alive; })[0] || null;
}
/* 把一次伤害分配给前排：嘲讽召唤物优先 → 否则第一个存活角色；角色掉光即倒下（不补位） */
function rlDamageSide(p, dmg) {
  var taunt = (p.summons || []).filter(function (u) { return u && u.taunt && u.sync > 0; })[0];
  if (taunt) {
    taunt.sync = Math.max(0, taunt.sync - dmg);
    showToast('🛡️ 嘲讽：召唤物承受 ' + dmg + ' 点伤害（剩余 ' + taunt.sync + '）', 'warn');
    if (taunt.sync <= 0) {
      p.summons = (p.summons || []).filter(function (u) { return u !== taunt; });
      showToast('召唤物被击破', 'warn');
    }
    return;
  }
  var tgt = rlAliveUnit(p);
  if (!tgt) { p.sync = Math.max(0, p.sync - dmg); return; }
  tgt.sync = Math.max(0, tgt.sync - dmg);
  if (tgt.sync <= 0) {
    tgt.alive = false;
    showToast('💔 ' + tgt.name + ' 倒下了（其被动与携带卡失效）', 'warn');
  }
  p.sync = p.units ? rlSumSync(p) : Math.max(0, p.sync - dmg);
}
/* 携带卡是否可用：卡所属角色必须在前排且未倒下 */
function rlCarryUsable(p, card) {
  if (!card || (!card.character && !card.character_full)) return true;   // 非携带卡
  var full = card.character_full || card.character;
  var short = String(full).split('·')[0].split('（')[0];
  var u = (p.units || []).filter(function (x) {
    return x.name === full || x.name === short || (x.full && (x.full === full || x.full === short));
  })[0];
  return u ? u.alive : false;
}

/* 背包被动：只要卡「存在于背包中」就生效（作者 2026-10 规则；不占后排格） */
function rlApplyBackpack(p) {
  var bag = (roguelikeState && roguelikeState.deck && roguelikeState.deck.items) || [];
  var has = function (n) { return bag.some(function (c) { return c && c.name === n; }); };
  if (has('四叶草发卡')) p.luck = (p.luck || 0) + 10;                     // 运气+10（每 10 点 ⇒ 判定骰 +1）
  if (has('共鸣者')) p.costRefillBonus = (p.costRefillBonus || 0) + 2;    // 每回合回复的音韵值+2
  if (has('执勤证明')) p.chaosBonus = (p.chaosBonus || 0) + 3;            // 自身造成的混沌属性伤害+3
  if (has('核心的供给者')) p.expBonus = (p.expBonus || 0) + 4;            // 战斗胜利经验+4（结算见 onRoguelikeBattleEnd）
  return p;
}

function rlStartTurn(player) {
  if (!rlState) return;
  rlState.currentPlayer = player;
  rlState.phase = 'prepare';
  var p = rlState[player];
  
  // 回费（背包被动「共鸣者」+2；角色 SP「自然回复音韵值+50%」乘算）
  var __rmul = (p.b && p.b.refillMul) ? (1 + p.b.refillMul / 100) : 1;
  p.cost = Math.min(p.cost + Math.round((5 + (p.costRefillBonus || 0)) * __rmul), p.maxCost);
  // 抽牌（含角色技能「准备阶段多抽」）
  rlDrawCard(player);
  var __ex = (p.b && p.b.extraDraw) || 0;
  for (var __i = 0; __i < __ex; __i++) rlDrawCard(player);
  // 回合开始类角色技能（仅玩家方前排第一位）
  if (player === 'p1') rlCharHook('turnStart');
  // 重置每回合一次的效果
  p.usedSkillsThisTurn = [];
  
  if (player === 'p2') {
    // 生成敌人意图
    rlGenerateEnemyIntent();
    setTimeout(rlEnemyAction, 600);
  }
  
  rlRenderUI();
}

function rlGenerateEnemyIntent() {
  if (!rlState) return;
  var p2 = rlState.p2;
  var intents = [
    { type: 'attack', value: 3 + Math.floor(rlState.turn/2), text: '⚔️ 攻击 ' + (3+Math.floor(rlState.turn/2)) },
    { type: 'attack', value: 5 + Math.floor(rlState.turn/3), text: '⚔️ 重击 ' + (5+Math.floor(rlState.turn/3)) },
    { type: 'defend', value: 4, text: '🛡️ 防御 +4护盾' },
    { type: 'buff', value: 2, text: '💪 强化 +2攻击' }
  ];
  p2.intent = intents[Math.floor(Math.random() * intents.length)];
}

function rlNextPhase() {
  if (!rlState || rlState.currentPlayer !== 'p1') return;
  if (rlState.phase === 'prepare') {
    rlState.phase = 'main';
  } else if (rlState.phase === 'main') {
    rlState.phase = 'end';
    rlEndTurn();
    return;
  }
  rlRenderUI();
}

function rlEndTurn() {
  if (!rlState) return;
  // 结束回合效果
  rlStartTurn('p2');
  setTimeout(function() {
    rlStartTurn('p1');
    rlState.turn++;
  }, 2000);
}

function rlEnemyAction() {
  if (!rlState || rlState.currentPlayer !== 'p2') return;
  var p2 = rlState.p2;
  var p1 = rlState.p1;
  var intent = p2.intent;
  
  if (!intent) { rlRenderUI(); return; }
  
  setTimeout(function() {
    if (intent.type === 'attack') {
      var dmg = intent.value;
      if (p1.shield > 0) { var shieldDmg = Math.min(p1.shield, dmg); p1.shield -= shieldDmg; dmg -= shieldDmg; }
      // 按布阵分配：嘲讽召唤物优先，其次前排第一位存活角色（掉光即倒下，战前编队不补位）
      rlDamageSide(p1, dmg);
    } else if (intent.type === 'defend') {
      p2.shield += intent.value;
    } else if (intent.type === 'buff') {
      p2.attackBuff += intent.value;
    }
    rlRenderUI();
    rlCheckBattleEnd();
  }, 800);
}

function rlPlayCard(handIndex) {
  if (!rlState || rlState.currentPlayer !== 'p1' || rlState.phase !== 'main') return;
  var p1 = rlState.p1;
  var card = p1.hand[handIndex];
  if (!card) return;
  
  var cost = card.cost || 0;
  // 角色技能：每张卡首次使用费用 -N（葵 / 惠 / 樱子）
  var __fm = (p1.b && p1.b.firstUseMinus) || 0;
  if (__fm) {
    p1._usedCards = p1._usedCards || {};
    if (!p1._usedCards[card.name]) { cost = Math.max(0, cost - __fm); p1._usedCards[card.name] = 1; }
  }
  if (!rlCarryUsable(p1, card)) {
    showToast('该角色不在场或已倒下，无法打出它的携带卡', 'warn');
    return;
  }
  if (p1.cost < cost) {
    showToast('费用不足！需要' + cost + '，当前' + p1.cost, 'warn');
    return;
  }
  
  p1.cost -= cost;
  p1.hand.splice(handIndex, 1);
  
  // 处理卡牌效果（把实际支付的音韵值传进去：红宝之杖·运 等要按支付量结算）
  rlProcessCardEffect(card, 'p1', 'p2', cost);
  // 用卡后触发（属性 / 同色 / 携带卡 条件由技能表判断）
  rlCharHook('afterCard', { attr: card.attribute, isCarry: !!(card.character_full),
                            sameAttr: (rlState.p1._lastAttr && rlState.p1._lastAttr === card.attribute) });
  rlState.p1._lastAttr = card.attribute;
  
  // 永续卡放入永续区，其他送入墓地
  if (card._category === 'item_permanent' || (card.type && card.type.indexOf('永续') >= 0)) {
    if (p1.permanent.length < 3) p1.permanent.push(card);
    else p1.grave.push(card);
  } else {
    p1.grave.push(card);
  }
  
  rlRenderUI();
  rlCheckBattleEnd();
}

/* ===== 肉鸽效果结算工具（2026-10 加：支持骰子式/公式/范围随机）===== */
function rlRollDice(expr) {                      // '1d12' '2d6' 'd6' → 点数和
  var m = String(expr).trim().match(/^(\d*)d(\d+)$/i);
  if (!m) return parseInt(expr, 10) || 0;
  var n = m[1] ? parseInt(m[1], 10) : 1, sides = parseInt(m[2], 10), sum = 0;
  for (var i = 0; i < n; i++) sum += 1 + Math.floor(Math.random() * sides);
  return sum;
}

/* 把效果文本里的一段「数值描述」算成数字：
   支持 1d12 / 2d6 / 1～3（范围随机）/ 「3+当前手卡数量」/ 「1+当前墓地中X属性卡的数量」/
   「等同于当前攻击力」/ 「当前攻击力×此卡发动时所消耗的音韵值」/ 纯数字 */
function rlAmount(expr, ctx) {
  var s = String(expr || '').replace(/[（）()]/g, '').replace(/点随机|点|的/g, '').trim();
  var m;
  if ((m = s.match(/^(\d*)d(\d+)$/i))) return rlRollDice(s) + Math.floor((ctx.p.luck || 0) / 10) + (((ctx.p.b || {}).judge) || 0);   // 运气 + 角色技能判定伤害加成
  if ((m = s.match(/^(\d+)[～~](\d+)$/))) {
    var lo = parseInt(m[1], 10), hi = parseInt(m[2], 10);
    return lo + Math.floor(Math.random() * (hi - lo + 1));
  }
  if ((m = s.match(/(\d+)\s*\+\s*当前手卡数量/))) return parseInt(m[1], 10) + ctx.p.hand.length;
  if ((m = s.match(/(\d+)\s*\+\s*当前墓地中(.+?)属性卡的数量/))) {
    return parseInt(m[1], 10) + ctx.graveCount(m[2]);
  }
  if (s.indexOf('当前攻击力×') >= 0 || s.indexOf('当前攻击力*') >= 0) {
    return ctx.attack() * (ctx.paid || 0);
  }
  if (s.indexOf('当前攻击力') >= 0) return ctx.attack();
  if ((m = s.match(/^(\d+)$/))) return parseInt(m[1], 10);
  return 0;
}

