  '柔软枕头': function (c) { c.heal(4); if (c.p.grave.length === 4 || c.p.grave.length === 6) c.draw(3); },
  '能量饮料': function (c) { c.p._nextDamageUp = (c.p._nextDamageUp || 0) + 3; },
  '崩塌之乌托邦': function (c) { c.healCost(2); },
