  '善意面具': function (c) { c.p.attackBuff += 2; },
  '结晶碎弧': function (c) { c.p._nextDamageUp = (c.p._nextDamageUp || 0) + 4; },
  '先哲之馈赠': function (c) { c.draw(2); c.mill(1); },
  '绿色宝杖': function (c) { c.noop(); },
  '绿宝之杖·择': function (c) { c.draw(2); c.p.sync = Math.max(0, c.p.sync - 4); },
  '鸣奏之“圣音”': function (c) { c.recall(); },
  '永奏进行曲': function (c) { c.draw(2); c.mill(1); },
  '妖刀五月雨': function (c) { c.damage(5, '混沌'); },
