/* 琉璃被动（判定伤害后）：回1音韵；每累计 3/6/11/14 次进入阶梯——抽2张、选1张送墓，之后全队判定伤害+1。
   2026-09-28 从 __finish 的手工 __cands.push 抽出，作为注册表触发 ruri-judge-passive 的效果本体。 */
function __ruriJudgeAfterDamage(owner) {
  try {
    var rp = battleState && battleState[owner]; if (!rp) return;
    recoverCost(owner, 1, '琉璃被动');
    addBattleLog(owner, '【琉璃被动】判定伤害后回复1音韵');
    rp._ruriJudgeCount = (rp._ruriJudgeCount || 0) + 1;
    var TH = [3, 6, 11, 14];
    if (TH.indexOf(rp._ruriJudgeCount) < 0) return;
    /* 【口径 (b) 2026-10-05】阶梯段（抽2选1弃 + 全队判定+1）必须先**谈窗询问发动**；
       "判定伤害后回1音韵"已在上方直接结算（作者口径：回音韵=直接，阶梯=谈窗）。 */
    var __ruriTierBody = function () {
    // 到达累计阈值：抽两张卡，然后选一张卡送入墓地，那之后全队造成的判定伤害+1
    if (typeof drawCard === 'function') { drawCard(owner); drawCard(owner); }
    function __ruriTier() {
      rp._judgeDamageBonus = (rp._judgeDamageBonus || 0) + 1;
      addBattleLog(owner, '【琉璃被动】累计' + rp._ruriJudgeCount + '次：抽2选1弃完成，全队判定伤害+1（当前+' + rp._judgeDamageBonus + '）');
      if (typeof updateBattleUI === 'function') updateBattleUI();
    }
    var dl = (typeof collectZoneCards === 'function') ? collectZoneCards(owner, ['hand'], null, null) : [];
    if (!dl.length) { __ruriTier(); return; }
    if (owner === 'p1' && typeof pickFromList === 'function') {
      pickFromList('p1', dl, '琉璃被动：抽2张后选1张送入墓地（那之后全队判定+1）', 1, function (picks) {
        picks.forEach(function (pk) {
          var arr = rp[pk.zone], ix = arr.indexOf(pk.card);
          if (ix >= 0) { arr.splice(ix, 1); rp.grave.push(pk.card); if (typeof checkGraveTrigger === 'function') checkGraveTrigger(owner, pk.card, 'effect'); }
        });
        __ruriTier();
      });
    } else {
      var pk = dl[0], arr = rp[pk.zone], ix = arr.indexOf(pk.card);
      if (ix >= 0) { arr.splice(ix, 1); rp.grave.push(pk.card); }
      __ruriTier();
    }
    };
    /* 谈窗询问：选"发动"才执行阶梯段；没有弹窗机制时按原样执行（兜底）。
       【S4 服务器权威 2026-10-05】服务器权威态下**不能**用 showChoiceModal ——
       它弹在**服务器**上、无人应答，实测被"AI闸门等待人类决策超时 ⇒ 放行"跳过，
       导致**客机的阶梯整个失效**（既不抽2也不弃1）。改走 ENV.ask 的**座位路由**，由该座位的客户端作答。
       非服务器权威（单机 / 普通联机）⇒ 保持原样，行为逐字不变。 */
    var __ruriAskTier = function (pick) { if (pick === 0) { try { __ruriTierBody(); } catch (e) {} } };
    try {
      /* 【统一决策通道 2026-10-06】谈窗**始终**走 ENV.ask ——
         它在本机走 __askChoiceLocal（测试床的 pickChoice 能答）、在服务器权威下走座位路由（由远端座位答）。
         原来这里直接调 showChoiceModal、绕过统一通道 ⇒ 测试床里**没人答** ⇒ 靠"AI闸门 2.4 秒放行"掩盖；
         真实对局里就表现为"谈窗没等到点击就被跳过 ⇒ 抽2选1弃整段消失"（作者实测）。 */
      if (typeof ENV !== 'undefined' && ENV && typeof ENV.ask === 'function') {
        ENV.ask(owner, { kind: 'choice', label: '琉璃被动·累计' + rp._ruriJudgeCount + '次',
          effect: '是否发动：抽2张、选1张送入墓地，那之后全队造成的判定伤害+1？',
          choices: ['发动', '不发动'] }, __ruriAskTier);
      } else if (typeof showChoiceModal === 'function') {
        showChoiceModal('琉璃被动·累计' + rp._ruriJudgeCount + '次', '是否发动：抽2张、选1张送入墓地，那之后全队造成的判定伤害+1？', null, ['发动', '不发动'], __ruriAskTier);
      } else { __ruriTierBody(); }
    } catch (e) { try { __ruriTierBody(); } catch (e2) {} }
  } catch (e) { console.error('琉璃被动·判定后处理出错', e); }
}

