  __tp._tempExiled.forEach(function (e) { (__tp[e.zone] = __tp[e.zone] || []).push(e.card); addBattleLog(player, '【结衣被动】回合结束，【' + e.card.name + '】返回' + (e.zone === 'hand' ? '手卡' : (e.zone === 'permanent' ? '效果处理区' : '盖伏区'))); });
