    if (typeof Online !== 'undefined' && Online.active && Online.mySide === 'p2') {
      battleState.round = (battleState.round || 1) + 1;
    }
    try { __replayCaptureTurn('p1'); } catch (e) {}
    // 切换到AI/远端
