    if (GameRNG.dice(6) >= 6) sc++;
    if (yu2) recoverCost(aiSeat(), 1, '躁动之心[入间予][AI]');
    if (sc > 0) p.fascination = Math.max(0, p.fascination - sc);
    L('躁动之心[AI]：校准成功' + sc + '次，降低' + sc + '点入迷（当前' + p.fascination + '）');
