        if (n >= 5) { p._sandRegenBonus = (p._sandRegenBonus || 0) + 1; __applied.push('自身每回合自然回复的音韵值+1（当前+' + p._sandRegenBonus + '）'); }
        if (n >= 7) { p._teamFinalDmgUp = (p._teamFinalDmgUp || 0) + 1; __applied.push('全队造成的最终伤害+1（当前+' + p._teamFinalDmgUp + '）'); }
        addBattleLog(user, '【堆沙堡】配对' + n + '次，按顺序执行：' + (__applied.length ? __applied.join('；') : '未达到1次配对，无效果'));
        if (typeof updateBattleUI === 'function') updateBattleUI();
